mapper.select:
select cv.id, c.customer_name customer_id, cl.linkman linkman_id, cv.visit_type, cv.visit_reason, cv.content, cv.visit_date, cv.input_user, cv.input_time from customer_visit cv left join customer_linkmane cl on cv.linkman_id = cl.id left join customer c on cv.customer_id = c.id
and cv.visit_type = #{visitType} and cv.visit_reason like concat('%', #{visitReason}, '%') and cv.visit_date between #{params.beginVisitDate} and #{params.endVisitDate}
ORDER BY id

mapper.update:
update customer_visit
customer_id = #{customerId}, linkman_id = #{linkmanId}, visit_type = #{visitType}, visit_reason = #{visitReason}, content = #{content}, visit_date = #{visitDate}, input_user = #{inputUser}, input_time = #{inputTime},
where id = #{id}
